import React, { useState, useEffect } from "react";
import { Plus, Layers, Trash2, Search, RefreshCw, Filter, Edit3, Image as ImageIcon } from "lucide-react";
import API_BASE from "../config";

const CategoryManager = () => {
    const [data, setData] = useState([]);
    const [loading, setLoading] = useState(true);

    const fetchData = async () => {
        try {
            const res = await fetch(`${API_BASE}/api/categories`, {
                headers: { "Authorization": `Bearer ${localStorage.getItem("token")}` }
            });
            const d = await res.json();
            setData(Array.isArray(d) ? d : []);
        } catch (e) { console.error(e); }
        finally { setLoading(false); }
    };

    useEffect(() => { fetchData(); }, []);

    return (
        <div className="space-y-3 animate-pro-in">
            <div className="flex items-center justify-between">
                <div className="space-y-0.5">
                    <h2 className="pro-heading">Category Orchestration</h2>
                    <p className="pro-subheading">Menu hierarchies and catalog classification protocols</p>
                </div>
                <div className="flex items-center gap-1.5">
                    <button onClick={fetchData} className="pro-btn-secondary h-7 px-2"><RefreshCw className="w-3 h-3" /> Sync</button>
                    <button className="pro-btn-primary h-7 px-3"><Plus className="w-3 h-3" /> New Category</button>
                </div>
            </div>

            <div className="pro-card p-2 flex items-center justify-between bg-white/50">
                <div className="flex items-center gap-2 flex-1">
                    <Search className="w-3.5 h-3.5 text-slate-400" />
                    <input type="text" placeholder="Search categories..." className="bg-transparent text-[12px] font-medium outline-none w-full" />
                </div>
                <button className="p-1.5 hover:bg-slate-100 rounded text-slate-400"><Filter className="w-3.5 h-3.5" /></button>
            </div>

            {loading ? (
                <div className="py-20 text-center pro-subheading animate-pulse">Syncing Catalog Vaults...</div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-4 lg:grid-cols-6 xl:grid-cols-8 gap-3">
                    {data.map(item => (
                        <div key={item.id} className="pro-card p-2 flex flex-col items-center gap-2 group hover:border-slate-400 transition-all text-center">
                            <div className="w-full aspect-square bg-slate-50 border border-slate-100 rounded overflow-hidden flex items-center justify-center text-slate-200">
                                {item.image_url ? (
                                    <img src={item.image_url} alt="" className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all" />
                                ) : (
                                    <ImageIcon className="w-6 h-6" />
                                )}
                            </div>
                            <div className="min-w-0 w-full px-1">
                                <h3 className="text-[11px] font-bold text-slate-900 truncate uppercase">{item.name}</h3>
                                <p className="text-[8px] font-black text-slate-300 uppercase tracking-widest">{item.outlet_name || 'Global'}</p>
                            </div>
                            <div className="flex items-center gap-1 mt-1">
                                <button className="p-1.5 hover:bg-slate-100 rounded text-slate-400"><Edit3 className="w-3 h-3" /></button>
                                <button className="p-1.5 hover:bg-rose-50 rounded text-rose-400"><Trash2 className="w-3 h-3" /></button>
                            </div>
                        </div>
                    ))}
                    {data.length === 0 && (
                        <div className="col-span-full py-20 text-center border border-dashed border-slate-200 rounded">
                            <Layers className="w-10 h-10 text-slate-200 mx-auto mb-2" />
                            <p className="pro-subheading">No Categories Defined</p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default CategoryManager;
