import React, { useState, useEffect } from "react";
import { Plus, UserCheck, Trash2, Search, RefreshCw, Filter, Edit3 } from "lucide-react";
import API_BASE from "../config";

const DesignationManager = () => {
    const [designations, setDesignations] = useState([]);
    const [loading, setLoading] = useState(true);
    const [newDesignation, setNewDesignation] = useState("");
    const [adding, setAdding] = useState(false);

    const fetchDesignations = async () => {
        try {
            const res = await fetch(`${API_BASE}/api/brand/designations`, {
                headers: { "Authorization": `Bearer ${localStorage.getItem("token")}` }
            });
            const data = await res.json();
            setDesignations(Array.isArray(data) ? data : []);
        } catch (e) { console.error(e); }
        finally { setLoading(false); }
    };

    useEffect(() => { fetchDesignations(); }, []);

    const handleAdd = async () => {
        if (!newDesignation.trim()) return;
        setAdding(true);
        try {
            const res = await fetch(`${API_BASE}/api/brand/designations`, {
                method: "POST",
                headers: { 
                    "Content-Type": "application/json",
                    "Authorization": `Bearer ${localStorage.getItem("token")}`
                },
                body: JSON.stringify({ name: newDesignation })
            });
            if (res.ok) {
                setNewDesignation("");
                fetchDesignations();
            }
        } catch (e) { console.error(e); }
        finally { setAdding(false); }
    };

    return (
        <div className="space-y-3 animate-pro-in">
            <div className="flex items-center justify-between">
                <div className="space-y-0.5">
                    <h2 className="pro-heading">Human Capital Matrix</h2>
                    <p className="pro-subheading">Staff designations and role-based hierarchies</p>
                </div>
                <div className="flex items-center gap-2">
                    <input 
                        type="text" 
                        value={newDesignation}
                        onChange={e => setNewDesignation(e.target.value)}
                        placeholder="Enter Designation..."
                        className="pro-input w-64"
                    />
                    <button 
                        onClick={handleAdd}
                        disabled={adding}
                        className="pro-btn-primary h-8"
                    >
                        {adding ? <RefreshCw className="w-3.5 h-3.5 animate-spin" /> : <Plus className="w-3.5 h-3.5" />}
                        Add Designation
                    </button>
                </div>
            </div>

            <div className="pro-card p-2 flex items-center justify-between bg-white/50">
                <div className="flex items-center gap-2 flex-1">
                    <Search className="w-3.5 h-3.5 text-slate-400" />
                    <input type="text" placeholder="Search designations..." className="bg-transparent text-[12px] font-medium outline-none w-full" />
                </div>
                <button className="p-1.5 hover:bg-slate-100 rounded text-slate-400"><Filter className="w-3.5 h-3.5" /></button>
            </div>

            {loading ? (
                <div className="py-20 text-center pro-subheading animate-pulse">Scanning Personnel Vaults...</div>
            ) : (
                <div className="pro-card overflow-hidden">
                    <table className="pro-table">
                        <thead>
                            <tr>
                                <th>Designation Identity</th>
                                <th>Protocol ID</th>
                                <th>Operational Status</th>
                                <th className="text-right">Operations</th>
                            </tr>
                        </thead>
                        <tbody>
                            {designations.map(d => (
                                <tr key={d.id} className="hover:bg-slate-50 transition-colors">
                                    <td className="font-bold text-slate-900 flex items-center gap-2">
                                        <UserCheck className="w-3.5 h-3.5 text-slate-400" /> {d.name}
                                    </td>
                                    <td className="text-[10px] font-bold text-slate-300 uppercase tracking-widest">DSG_{d.id.toString().padStart(3, '0')}</td>
                                    <td>
                                        <span className="px-2 py-0.5 rounded bg-slate-50 border border-slate-200 text-[9px] font-bold uppercase text-slate-500">Active</span>
                                    </td>
                                    <td className="text-right">
                                        <div className="flex items-center justify-end gap-1">
                                            <button className="p-1.5 hover:bg-slate-100 rounded text-slate-400"><Edit3 className="w-3 h-3" /></button>
                                            <button className="p-1.5 hover:bg-rose-50 rounded text-rose-400"><Trash2 className="w-3 h-3" /></button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                            {designations.length === 0 && (
                                <tr><td colSpan="4" className="py-20 text-center pro-subheading">No Designations Defined</td></tr>
                            )}
                        </tbody>
                    </table>
                </div>
            )}
        </div>
    );
};

export default DesignationManager;
