import React, { useState, useEffect } from "react";
import API_BASE from "../config";
import { 
  TrendingUp, Users, ShoppingCart, IndianRupee, 
  ArrowUpRight, ArrowDownRight, Activity, 
  RefreshCw, Smartphone, Monitor, Loader2, Zap,
  Calendar, Plus, BarChart3, CreditCard, ChevronDown,
  Clock, Package, Home, Globe, Building2
} from "lucide-react";

const Dashboard = () => {
    const [stats, setStats] = useState({
        totalRevenue: 0,
        netSales: 0,
        offlineSales: 0,
        onlineSales: 0,
        totalOrders: 0,
        totalCustomers: 0
    });
    const [loading, setLoading] = useState(true);
    const [outlets, setOutlets] = useState([]);
    const [fleetLoading, setFleetLoading] = useState(false);

    const user = JSON.parse(localStorage.getItem("user") || "{}");

    useEffect(() => {
        const fetchData = async () => {
            try {
                setLoading(true);
                const impersonateId = sessionStorage.getItem("impersonate_id");
                const targetParam = impersonateId ? `?target_user_id=${impersonateId}` : "";
                const res = await fetch(`${API_BASE}/api/orders${targetParam}`, {
                    headers: { "Authorization": `Bearer ${localStorage.getItem("token")}` }
                });
                const data = await res.json();
                
                if (Array.isArray(data)) {
                    const revenue = data.reduce((acc, curr) => acc + (parseFloat(curr.total_price) || 0), 0);
                    const online = data.filter(o => o.order_type === 'online' || o.source === 'online').reduce((acc, curr) => acc + (parseFloat(curr.total_price) || 0), 0);
                    
                    setStats({
                        totalRevenue: revenue,
                        netSales: revenue * 0.95, // Simulated net sales
                        offlineSales: revenue - online,
                        onlineSales: online,
                        totalOrders: data.length,
                        totalCustomers: new Set(data.map(o => o.customer_phone)).size
                    });
                }
            } catch (err) {
                console.error("Dashboard Fetch Error:", err);
            } finally {
                setLoading(false);
            }
        };

        const fetchFleet = async () => {
            if (user?.role !== 'brand_owner') return;
            try {
                setFleetLoading(true);
                const res = await fetch(`${API_BASE}/api/auth/my-outlets`, {
                    headers: { "Authorization": `Bearer ${localStorage.getItem("token")}` }
                });
                const data = await res.json();
                if (res.ok) setOutlets(data);
            } catch (err) { console.error(err); }
            finally { setFleetLoading(false); }
        };

        fetchData();
        fetchFleet();
    }, []);

    if (loading) return (
        <div className="h-[80vh] w-full flex flex-col items-center justify-center">
            <Loader2 className="w-8 h-8 text-blue-500 animate-spin mb-4" />
            <p className="text-[11px] font-bold text-slate-500 uppercase tracking-[0.3em]">Calibrating Revenue Intelligence...</p>
        </div>
    );

    const handleManageOutlet = (id) => {
        sessionStorage.setItem("impersonate_id", id);
        window.location.reload();
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500 pb-10">
            {/* TMBill Style Header */}
            <div className="flex items-center justify-between bg-white dark:bg-[#1e2129] border-b border-slate-200 dark:border-white/5 px-6 py-4 -mx-6 -mt-6 sticky top-0 z-10 shadow-lg">
                <div className="flex items-center gap-4">
                    <div className="p-2 bg-blue-600/10 rounded-lg">
                        <BarChart3 className="w-5 h-5 text-blue-500" />
                    </div>
                    <h2 className="text-[16px] font-bold text-slate-800 dark:text-white uppercase tracking-tight">Revenue Dashboard</h2>
                </div>
                
                <div className="text-center hidden lg:block">
                    <p className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-[0.2em]">{user?.business_name || "Enterprise Cluster"} - {user?.business_type || "Operations"}</p>
                </div>


                <div className="flex items-center gap-3">
                    <div className="flex items-center gap-2 bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/5 rounded-md px-4 py-2 cursor-pointer hover:bg-slate-100 dark:hover:bg-white/10 transition-all">
                        <Calendar className="w-3.5 h-3.5 text-slate-400" />
                        <span className="text-[10px] font-bold text-slate-600 dark:text-slate-300 uppercase">08 May 2026 - 08 May 2026</span>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 p-6">
                {/* Brand Owner Fleet Directory */}
                {user.role === 'brand_owner' && outlets.length > 0 && !sessionStorage.getItem("impersonate_id") && (
                    <div className="lg:col-span-12 space-y-4">
                        <div className="flex items-center justify-between">
                            <h3 className="text-[13px] font-bold text-indigo-600 dark:text-indigo-400 uppercase tracking-wider">Enterprise Fleet Directory</h3>
                            <span className="text-[10px] font-black text-slate-400 uppercase">{outlets.length} Active Nodes</span>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                            {outlets.map(o => (
                                <div key={o.id} className="bg-white dark:bg-[#1e2129] border border-slate-200 dark:border-white/5 rounded-xl p-5 group hover:border-indigo-500/30 transition-all shadow-sm">
                                    <div className="flex justify-between items-start mb-4">
                                        <div className="w-10 h-10 rounded-lg bg-indigo-50 dark:bg-indigo-500/10 flex items-center justify-center">
                                            <Building2 className="w-5 h-5 text-indigo-500" />
                                        </div>
                                        <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded ${o.status === 'active' ? 'bg-emerald-500/10 text-emerald-600' : 'bg-rose-500/10 text-rose-600'}`}>
                                            {o.status}
                                        </span>
                                    </div>
                                    <h4 className="text-[14px] font-bold text-slate-800 dark:text-white uppercase tracking-tight truncate">{o.business_name}</h4>
                                    <p className="text-[10px] text-slate-400 dark:text-slate-500 font-bold uppercase mt-1 mb-6">{o.business_type?.replace(/_/g, ' ')}</p>
                                    
                                    <button 
                                        onClick={() => handleManageOutlet(o.id)}
                                        className="w-full py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg text-[10px] font-black uppercase tracking-widest transition-all shadow-lg shadow-indigo-600/20"
                                    >
                                        Enter Dashboard
                                    </button>
                                </div>
                            ))}
                            {fleetLoading && (
                                <div className="col-span-full py-10 flex flex-col items-center">
                                    <Loader2 className="w-5 h-5 text-indigo-500 animate-spin mb-2" />
                                    <p className="text-[9px] font-bold text-slate-400 uppercase">Synchronizing Nodes...</p>
                                </div>
                            )}
                        </div>
                    </div>
                )}

                {/* Sales Statistics (2x2 Grid) */}
                <div className="lg:col-span-7 space-y-6">
                    <h3 className="text-[13px] font-bold text-blue-600 dark:text-blue-400 uppercase tracking-wider mb-4">Sales Statistics</h3>
                    <div className="grid grid-cols-2 gap-4">
                        {[
                            { label: 'Total Sales', val: stats.totalRevenue, icon: TrendingUp, color: 'blue' },
                            { label: 'Net Sales', val: stats.netSales, icon: Activity, color: 'indigo' },
                            { label: 'Offline Sales', val: stats.offlineSales, icon: Home, color: 'slate' },
                            { label: 'Online Sales', val: stats.onlineSales, icon: ShoppingCart, color: 'emerald' }
                        ].map(card => (
                            <div key={card.label} className="bg-white dark:bg-[#1e2129] border border-slate-200 dark:border-white/5 rounded-xl p-6 group hover:border-blue-500/30 transition-all shadow-sm">
                                <div className="flex items-center gap-6">
                                    <div className="relative">
                                        <div className={`w-16 h-16 rounded-full border-4 border-slate-100 dark:border-white/5 flex items-center justify-center text-${card.color}-500 group-hover:scale-110 transition-transform`}>
                                            <card.icon className="w-6 h-6" />
                                        </div>
                                        <svg className="absolute inset-0 w-full h-full -rotate-90">
                                            <circle cx="32" cy="32" r="30" fill="none" stroke="currentColor" strokeWidth="4" className="text-slate-100 dark:text-blue-600/20" />
                                            <circle cx="32" cy="32" r="30" fill="none" stroke="currentColor" strokeWidth="4" strokeDasharray="188.4" strokeDashoffset="40" className="text-blue-500" />
                                        </svg>
                                    </div>
                                    <div>
                                        <p className="text-[12px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest">{card.label}</p>
                                        <h3 className="text-[20px] font-black text-slate-800 dark:text-white tracking-tighter mt-1">Rs {card.val.toLocaleString('en-IN')} <span className="text-[10px] text-slate-400 font-bold">(0)</span></h3>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Payment Statistics Card */}
                <div className="lg:col-span-5 flex flex-col">
                    <h3 className="text-[13px] font-bold text-blue-600 dark:text-blue-400 uppercase tracking-wider mb-4">Payment Statistics (0.00)</h3>
                    <div className="flex-1 bg-white dark:bg-[#1e2129] border border-slate-200 dark:border-white/5 rounded-xl p-8 flex flex-col items-center justify-center relative overflow-hidden group shadow-sm">
                        <div className="relative z-10 flex flex-col items-center text-center space-y-6">
                            <div className="relative">
                                <div className="w-32 h-32 bg-blue-600/5 rounded-full flex items-center justify-center border border-slate-100 dark:border-white/5 animate-pulse">
                                    <CreditCard className="w-12 h-12 text-blue-500/40" />
                                </div>
                                <div className="absolute -right-4 -bottom-4 w-12 h-12 bg-white dark:bg-white/5 rounded-xl flex items-center justify-center border border-slate-200 dark:border-white/5 rotate-12 shadow-sm">
                                    <IndianRupee className="w-6 h-6 text-slate-400" />
                                </div>
                            </div>
                            <div className="space-y-2">
                                <p className="text-[14px] font-bold text-slate-800 dark:text-white uppercase tracking-tight">No Payment Artifacts</p>
                                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Execute transaction audit to populate manifest</p>
                            </div>
                        </div>
                        
                        <div className="absolute inset-0 opacity-[0.03] flex items-center justify-center pointer-events-none group-hover:scale-110 transition-transform duration-[2000ms]">
                            <Activity className="w-64 h-64 text-blue-500" />
                        </div>
                    </div>
                </div>

                {/* Hourly Revenue Analysis */}
                <div className="lg:col-span-12 space-y-4">
                    <div className="flex items-center justify-between">
                        <h3 className="text-[13px] font-bold text-blue-600 dark:text-blue-400 uppercase tracking-wider">Hourly Revenue Analysis</h3>
                        <button className="p-1 hover:bg-slate-100 dark:hover:bg-white/5 rounded transition-all text-slate-400"><ChevronDown className="w-4 h-4" /></button>
                    </div>
                    <div className="bg-white dark:bg-[#1e2129] border border-slate-200 dark:border-white/5 rounded-xl p-12 min-h-[300px] flex flex-col items-center justify-center text-center group shadow-sm">
                        <div className="space-y-4 opacity-20 group-hover:opacity-40 transition-opacity">
                            <BarChart3 className="w-16 h-16 text-slate-400 mx-auto" />
                            <div>
                                <p className="text-[14px] font-black text-slate-800 dark:text-white uppercase tracking-[0.2em]">No Data Found</p>
                                <p className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest mt-1">Temporal analysis requires live transaction stream</p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Platform Footer */}
            <div className="border-t border-slate-100 dark:border-white/5 px-6 py-4 flex flex-col md:flex-row items-center justify-between text-[10px] font-bold text-slate-400 dark:text-slate-600 uppercase tracking-widest">
                <p>Copyright © 2026-2027 <span className="text-blue-500">Powered by SaSLoop AI Technology LLC</span>. All Rights Reserved.</p>
                <div className="flex items-center gap-6 mt-4 md:mt-0">
                    <p>Version: <span className="text-slate-500">11.7.0</span></p>
                    <p className="text-blue-500/60 cursor-pointer hover:text-blue-500 transition-colors">support@sasloop.ai</p>
                </div>
            </div>
        </div>
    );
};

export default Dashboard;
